class TodoManager:
    def __init__(self):
        self.todos = {}
        self.next_id = 1
    def add_task(self, title):
        tid = self.next_id
        self.todos[tid] = {"id": tid, "title": title, "completed": False}
        self.next_id += 1
        return self.todos[tid]
    def get_task(self, task_id):
        return self.todos.get(task_id)
    def toggle_task(self, task_id):
        if task_id in self.todos:
            self.todos[task_id]["completed"] = not self.todos[task_id]["completed"]
            return self.todos[task_id]
        return None
    def delete_task(self, task_id):
        return self.todos.pop(task_id, None)

mgr = TodoManager()
t = mgr.add_task("Study Python")
print(mgr.toggle_task(t["id"]))

from sqlalchemy import Column, Integer, String, Boolean, DateTime
from sqlalchemy.ext.declarative import declarative_base
from datetime import datetime

Base = declarative_base()

class Task(Base):
    __tablename__ = 'tasks'
    id = Column(Integer, primary_key=True)
    title = Column(String(255), nullable=False)
    due_date = Column(DateTime)
    is_deleted = Column(Boolean, default=False)

    def to_dict(self):
        return {
            'id': self.id,
            'title': self.title,
            'due_date': self.due_date.isoformat() if self.due_date else None,
            'is_deleted': self.is_deleted
        }

def get_active_query(session):
    return session.query(Task).filter_by(is_deleted=False)

def delete_task(session, task_id):
    task = session.query(Task).get(task_id)
    if task is None:
        return False
    task.is_deleted = True
    session.commit()
    return True
